export const envelope = [90, 35, 90];

export default function build(api) {
  const cx = 45;
  const cz = 45;

  const put = (x, y, z, block) => {
    api.set(x, y, z, block);
  };

  const profile = [
    [10, 10, 10],
    [11, 22, 20],
    [12, 30, 28],
    [13, 35, 33],
    [14, 39, 36],
    [15, 41, 38],
    [16, 42, 39],
    [17, 42, 40],
    [18, 41, 39],
    [19, 40, 38],
    [20, 38, 36],
    [21, 35, 33],
    [22, 32, 30],
    [23, 29, 27],
    [24, 26, 24],
    [25, 22, 21],
    [26, 18, 17],
    [27, 14, 13],
    [28, 10, 9],
    [29, 7, 6],
    [30, 4, 4]
  ];

  for (let pi = 0; pi < profile.length; pi++) {
    const y = profile[pi][0];
    const rx = profile[pi][1];
    const rz = profile[pi][2];

    for (let x = cx - rx; x <= cx + rx; x++) {
      for (let z = cz - rz; z <= cz + rz; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const q = (dx * dx) / (rx * rx) + (dz * dz) / (rz * rz);

        if (q <= 1) {
          const pattern = (x * 17 + z * 31 + y * 13) % 47;
          let block = "minecraft:deepslate";

          if (pattern < 13) {
            block = "minecraft:polished_blackstone";
          } else if (pattern < 20) {
            block = "minecraft:obsidian";
          } else if (pattern < 27) {
            block = "minecraft:crying_obsidian";
          }

          if (q > 0.84 && pattern % 7 === 0) {
            block = "minecraft:oxidized_copper";
          }

          if (q > 0.94 && pattern % 11 === 0) {
            block = "minecraft:iron_block";
          }

          put(x, y, z, block);
        }
      }
    }
  }

  for (let dx = -11; dx <= 11; dx++) {
    for (let dz = -11; dz <= 11; dz++) {
      const d2 = dx * dx + dz * dz;

      if (d2 <= 121) {
        let block = "minecraft:polished_blackstone";

        if (d2 <= 4) {
          block = "minecraft:glowstone";
        } else if (d2 <= 16) {
          block = "minecraft:cyan_concrete";
        } else if (d2 <= 36) {
          block = "minecraft:purple_concrete";
        } else if (d2 % 7 === 0) {
          block = "minecraft:oxidized_copper";
        }

        put(cx + dx, 0, cz + dz, block);
      }
    }
  }

  const beamRadii = [7, 6, 6, 5, 5, 4, 4, 4, 5, 6, 8];

  for (let y = 0; y <= 10; y++) {
    const r = beamRadii[y];

    for (let dx = -r; dx <= r; dx++) {
      for (let dz = -r; dz <= r; dz++) {
        const d2 = dx * dx + dz * dz;

        if (d2 <= r * r) {
          let block;

          if (d2 === 0) {
            block = "minecraft:glowstone";
          } else if (d2 >= (r - 1) * (r - 1)) {
            block = "minecraft:lime_concrete";
          } else if ((xOrZero(dx) + zOrZero(dz) + y) % 3 === 0) {
            block = "minecraft:cyan_concrete";
          } else {
            block = "minecraft:purple_concrete";
          }

          put(cx + dx, y, cz + dz, block);
        }
      }
    }
  }

  for (let i = 0; i < 16; i++) {
    const angle = Math.PI * 2 * i / 16;
    const ca = Math.cos(angle);
    const sa = Math.sin(angle);

    for (let step = 1; step <= 4; step++) {
      const r = step * 2;

      for (let w = -1; w <= 1; w++) {
        const x = Math.round(cx + ca * r - sa * w);
        const z = Math.round(cz + sa * r + ca * w);
        const dx = x - cx;
        const dz = z - cz;

        if (dx * dx + dz * dz <= 100) {
          let block = "minecraft:obsidian";

          if (step <= 2 && (i + w) % 4 === 0) {
            block = "minecraft:glowstone";
          } else if (step === 3) {
            block = "minecraft:oxidized_copper";
          } else if (step === 4) {
            block = "minecraft:crying_obsidian";
          }

          put(x, 10, z, block);
        }
      }
    }
  }

  for (let i = 0; i < 12; i++) {
    const angle = Math.PI * 2 * i / 12;
    const ca = Math.cos(angle);
    const sa = Math.sin(angle);

    for (let y = 12; y <= 28; y++) {
      const row = profile[y - 10];
      const rx = row[1];
      const rz = row[2];
      const edge = 1 / Math.sqrt(
        (ca * ca) / (rx * rx) +
        (sa * sa) / (rz * rz)
      );

      for (let inset = 1; inset <= 3; inset++) {
        const rr = edge - inset;

        if (rr > 0) {
          const x = Math.round(cx + ca * rr);
          const z = Math.round(cz + sa * rr);
          const dx = x - cx;
          const dz = z - cz;
          const q = (dx * dx) / (rx * rx) + (dz * dz) / (rz * rz);

          if (q <= 1) {
            let block;

            if (inset === 1) {
              block = i % 2 === 0
                ? "minecraft:oxidized_copper"
                : "minecraft:crying_obsidian";
            } else if (inset === 2) {
              block = "minecraft:polished_blackstone";
            } else {
              block = "minecraft:obsidian";
            }

            put(x, y, z, block);
          }
        }
      }
    }
  }

  const dome = [
    [29, 8],
    [30, 7],
    [31, 5],
    [32, 4],
    [33, 2],
    [34, 1]
  ];

  for (let di = 0; di < dome.length; di++) {
    const y = dome[di][0];
    const r = dome[di][1];

    for (let dx = -r; dx <= r; dx++) {
      for (let dz = -r; dz <= r; dz++) {
        const d2 = dx * dx + dz * dz;

        if (d2 <= r * r) {
          let block;

          if (d2 === 0 && y >= 30) {
            block = "minecraft:glowstone";
          } else if (d2 === 0) {
            block = "minecraft:iron_block";
          } else if (d2 >= (r - 1) * (r - 1)) {
            block = y % 2 === 0
              ? "minecraft:purple_concrete"
              : "minecraft:cyan_concrete";
          } else if ((dx + dz + y) % 3 === 0) {
            block = "minecraft:amethyst_block";
          } else {
            block = "minecraft:crying_obsidian";
          }

          put(cx + dx, y, cz + dz, block);
        }
      }
    }
  }

  const podPositions = [
    [cx + 18, cz],
    [cx - 18, cz],
    [cx, cz + 16],
    [cx, cz - 16]
  ];

  for (let p = 0; p < podPositions.length; p++) {
    const px = podPositions[p][0];
    const pz = podPositions[p][1];

    for (let level = 0; level < 4; level++) {
      const y = 25 + level;
      const r = level < 2 ? 2 : level === 2 ? 1 : 0;

      for (let dx = -r; dx <= r; dx++) {
        for (let dz = -r; dz <= r; dz++) {
          const d2 = dx * dx + dz * dz;

          if (d2 <= r * r) {
            let block;

            if (level === 3 && d2 === 0) {
              block = "minecraft:glowstone";
            } else if (d2 === 0) {
              block = "minecraft:iron_block";
            } else if (level < 2) {
              block = "minecraft:amethyst_block";
            } else {
              block = "minecraft:purple_concrete";
            }

            put(px + dx, y, pz + dz, block);
          }
        }
      }
    }
  }

  const emitterPositions = [
    [cx + 5, cz],
    [cx - 5, cz],
    [cx, cz + 5],
    [cx, cz - 5]
  ];

  for (let p = 0; p < emitterPositions.length; p++) {
    const px = emitterPositions[p][0];
    const pz = emitterPositions[p][1];

    for (let y = 8; y <= 10; y++) {
      for (let dx = -1; dx <= 1; dx++) {
        for (let dz = -1; dz <= 1; dz++) {
          if (dx * dx + dz * dz <= 1) {
            let block = "minecraft:iron_block";

            if (dx === 0 && dz === 0 && y === 9) {
              block = "minecraft:glowstone";
            } else if ((dx + dz + y + p) % 2 === 0) {
              block = "minecraft:oxidized_copper";
            }

            put(px + dx, y, pz + dz, block);
          }
        }
      }
    }
  }

  for (let x = cx - 3; x <= cx + 3; x++) {
    const dx = x - cx;

    for (let y = 16; y <= 21; y++) {
      const row = profile[y - 10];
      const span = Math.floor(
        row[2] * Math.sqrt(1 - (dx * dx) / (row[1] * row[1]))
      );
      const z = cz - span - 1;
      let block = "minecraft:purple_concrete";

      if (Math.abs(dx) === 3 || y === 16 || y === 21) {
        block = "minecraft:iron_block";
      } else if (dx === 0 && y === 18) {
        block = "minecraft:glowstone";
      } else if ((x + y) % 3 === 0) {
        block = "minecraft:cyan_concrete";
      }

      put(x, y, z, block);
    }
  }

  return {
    name: "Mothership Command Vessel",
    seatY: 0,
    anchors: {
      door: [cx, 0, cz - 11],
      beam: [cx, 5, cz],
      hatch: [cx, 18, cz - 40],
      core: [cx, 34, cz]
    }
  };
}

function xOrZero(value) {
  return value;
}

function zOrZero(value) {
  return value;
}

